from __future__ import annotations

def piercing_lower_bound(n: int) -> int:
    if n < 0: raise ValueError("n must be nonnegative")
    return (n + 1) // 2

def main() -> None:
    n, packing = 64, 16
    lower = piercing_lower_bound(n)
    ceiling = 2 * packing - 1
    print({"members": n, "packing": packing, "piercing_lower_bound": lower, "proposed_ceiling": ceiling})
    assert ceiling < lower

if __name__ == "__main__": main()

from __future__ import annotations

def closed_form(level: int) -> int:
    if level < 0: raise ValueError("level must be nonnegative")
    return 4 ** (2 ** level)

def iterative(level: int) -> int:
    if level < 0: raise ValueError("level must be nonnegative")
    value = 4
    for _ in range(level): value **= 2
    return value

def main() -> None:
    rows = [(r, closed_form(r), iterative(r)) for r in range(4)]
    print(rows)
    assert all(a == b for _, a, b in rows)

if __name__ == "__main__": main()

