from __future__ import annotations
from collections.abc import Hashable, Mapping
from typing import TypeVar
Q = TypeVar("Q", bound=Hashable)

def capacity_bound(capacities: Mapping[Q, int]) -> int:
    if any(c < 0 for c in capacities.values()): raise ValueError("negative capacity")
    return sum(capacities.values())

if __name__ == "__main__":
    cells = {(p, q): 1 for p in range(4) for q in range(4)}
    print(capacity_bound(cells))

from __future__ import annotations
from dataclasses import dataclass
from itertools import combinations
from collections.abc import Sequence
@dataclass(frozen=True)
class Rectangle:
    left: float; right: float; bottom: float; top: float

def point_triangle_free(rs: Sequence[Rectangle]) -> bool:
    for a, b, c in combinations(rs, 3):
        if (max(a.left,b.left,c.left) <= min(a.right,b.right,c.right) and
            max(a.bottom,b.bottom,c.bottom) <= min(a.top,b.top,c.top)):
            return False
    return True

if __name__ == "__main__":
    print(point_triangle_free([Rectangle(0,2,0,1), Rectangle(1,3,0,1), Rectangle(4,5,0,1)]))

from __future__ import annotations
from collections.abc import Sequence

def recursive_scales(max_level: int) -> Sequence[int]:
    if max_level < 0: raise ValueError("max_level must be nonnegative")
    values = [4]
    for _ in range(max_level): values.append(values[-1] ** 2)
    return values

if __name__ == "__main__": print(list(recursive_scales(3)))

